floor_fn:
"""
    Splits rna into codons.

    Args:
        rna (str): RNA string.

    Returns:
        list: codons.
    """
def codons(rna: Any) -> object {
    return [
        rna[index:(index + 3)]
        for index in range(0, len(rna), 3)
        if (len(rna[index:(index + 3)]) == 3)
    ];
}

test_blocks:
test "t0" {
    assert (codons('UUU') == ['UUU']);;
}

test "t1" {
    assert (codons('') == []);;
}

test "t2" {
    assert (codons('AUGAUG') == ['AUG', 'AUG']);;
}

test "t3" {
    assert (codons('AUGAUGAUGAUG') == ['AUG', 'AUG', 'AUG', 'AUG']);;
}

test "t4" {
    assert (codons('AUG') == ['AUG']);;
}

test "t5" {
    assert (codons('AAA') == ['AAA']);;
}

test "t6" {
    assert (codons('AUGAUGAUG') == ['AUG', 'AUG', 'AUG']);;
}

test "t7" {
    assert (codons('UUA') == ['UUA']);;
}
